  const c0 = p0;
  const c1 = v0 * T;
  const c2 = 0.5 * a0 * T * T;
  const dp = p1 - p0 - c1 - c2;
  const dv = (v1 - v0 - a0 * T) * T;
  const da = (a1 - a0) * T * T;
