  { t: 2.6, p: [-1.15, 1.05, -0.85], v: [0.6, 0, 0], a: [0, 0, 0] },
  { t: 5.4, p: [0.15, 1.40, 0.25], v: [0.6, 0, 0], a: [0, 0, 0] },
  { t: 8.0, p: [1.35, 1.05, 1.05], v: [0.6, 0, 0], a: [0, 0, 0] },
  { t: 10.6, p: [2.05, 0.08, 1.65], v: [0, 0, 0], a: [0, 0, 0] },
