      return inertia * (65 * (0.6 - state.att[axis]) - 13 * state.rates[axis] + 22 * intMax) - dTauEst;
    };

    const dEst0 = params.weakness > 0 ? thrustSym * 4.0 * params.weakness / (1 - params.weakness) : 0;
    tauRollSym = clamp(tauRollSym, minTauAxis('roll', TASK.arm * MOTOR_Z[w] * dEst0), maxTauAxis('roll', TASK.arm * MOTOR_Z[w] * dEst0));
