    const deltaD = desiredW - targetW;

    const dRollTau = TASK.arm * MOTOR_Z[w] * deltaD;
    const dPitchTau = -TASK.arm * MOTOR_X[w] * deltaD;
    const dYawTau = TASK.yawCoefficient * SPIN[w] * deltaD;

