function buildWaypoints(p0, offsets) {
  const o = offsets || [
    { y: 0, z: 0 },
    { y: 0, z: 0 },
    { y: 0, z: 0 },
  ];
  return [
    { t: 0.0, p: [p0.x, p0.y, p0.z], v: [0, 0, 0], a: [0, 0, 0] },
    { t: 2.5, p: [-1.15, 1.05 + o[0].y, -0.85 + o[0].z], v: [0.65, 0, 0], a: [0, 0, 0] },
    { t: 5.2, p: [0.15, 1.40 + o[1].y, 0.25 + o[1].z], v: [0.65, 0, 0], a: [0, 0, 0] },
    { t: 7.8, p: [1.35, 1.05 + o[2].y, 1.05 + o[2].z], v: [0.65, 0, 0], a: [0, 0, 0] },
    { t: 10.4, p: [2.05, 0.085, 1.65], v: [0, 0, 0], a: [0, 0, 0] },
  ];
}

function sampleTrajectory(wps, t) {
  const last = wps[wps.length - 1];
  if (t >= last.t) {
    return {
      p: { x: last.p[0], y: last.p[1], z: last.p[2] },
      v: { x: 0, y: 0, z: 0 },
      a: { x: 0, y: 0, z: 0 },
      j: { x: 0, y: 0, z: 0 },
    };
  }
  let idx = 0;
  while (idx < wps.length - 2 && t >= wps[idx + 1].t) idx++;
