  const ayDes = ref.a.y + kpY * (ref.p.y - state.pos.y) + kdY * (ref.v.y - state.vel.y);
  const azDes = ref.a.z + kp * (ref.p.z - state.pos.z) + kd * (ref.v.z - state.vel.z);

