        const nz = (nr() + nr() + nr() - 1.5) * 0.001;
        if (Math.abs(x0 + nx - obs0.pos.x) < 1e-11 &&
            Math.abs(0.07 + ny - obs0.pos.y) < 1e-11 &&
            Math.abs(z0 + nz - obs0.pos.z) < 1e-11) {
          return s;
        }
      }
