function quintic1D(p0, v0, a0, p1, v1, a1, T, t) {
  const s = clamp(t / T, 0, 1);
  const s2 = s * s, s3 = s2 * s, s4 = s3 * s, s5 = s4 * s;
  const c0 = p0;
  const c1 = v0 * T;
  const c2 = 0.5 * a0 * T * T;
  const dp = p1 - p0 - c1 - c2;
  const dv = (v1 - v0 - a0 * T) * T;
  const da = (a1 - a0) * T * T;
